// Elaboración didáctica basada exclusivamente en las relaciones y fuentes indicadas.
import { extraLessons, enrichLessons } from './guide.mjs';
export { referenceCards } from './guide.mjs';
const section = (title, paragraphs, code, language = 'csharp', filename = 'Fragmento de estudio') => ({ title, paragraphs, code, language, filename });
const quiz = (question, options, answer, explanation) => ({ question, options, answer, explanation });
export const lessons = [
  {
    id: 'entorno', unit: 'UD2', title: 'Preparar Android y entender el proyecto', tag: 'Preparación', minutes: 20,
    summary: 'Qué hace el SDK Manager, qué hace el Device Manager y cómo empezar a probar la interfaz.',
    sources: ['ConfiguracionMAUI', 'MSLearn02DisenioIUJesusCG'],
    goals: ['Distinguir instalación de SDK y creación de dispositivos.', 'Localizar XAML, code-behind y punto de arranque en los proyectos recibidos.'],
    sections: [
      section('1. SDK Manager: las herramientas de compilación', ['El PDF de configuración separa dos responsabilidades. Android SDK Manager instala, actualiza y elimina componentes del SDK: plataformas Android, herramientas e imágenes de sistema. La plataforma proporciona las API para compilar; la imagen de sistema permite ejecutar una versión de Android en el emulador. No son el mismo elemento.', 'El profesor muestra API 34 y dos imágenes para procesadores Intel Atom de 64 bits. Es una configuración mostrada en el documento, no una obligación universal de instalar exactamente esas versiones. El propio PDF advierte que instalar muchas API e imágenes ocupa mucho disco. Antes de cambiar tu entorno, comprueba las capturas del original y los destinos que ya tiene tu proyecto.']),
      section('2. Device Manager: el dispositivo donde pruebas', ['Android Device Manager crea los dispositivos virtuales: tipo de dispositivo, resolución e imagen con la que arrancará. Tener el SDK instalado no crea automáticamente el emulador que vas a usar. Primero necesitas los componentes y después un dispositivo configurado con una imagen disponible.', 'En una práctica de interfaces, comprueba que la aplicación arranca y que puedes pulsar, escribir y leer mensajes. Una compilación correcta no demuestra que un formulario se vea bien en una pantalla más pequeña. El documento tiene capturas de configuración: consúltalas en la biblioteca para ver la distribución exacta de las herramientas.']),
      section('3. Recorrer uno de los proyectos entregados', ['En el RAR MSLearn02DisenioIUJesusCG hay aplicaciones con MainPage.xaml y su archivo MainPage.xaml.cs. XAML declara el árbol visual; el code-behind define el comportamiento. Son dos partes de la misma clase cuando coinciden x:Class, namespace y nombre de clase.', 'InitializeComponent() carga la interfaz declarada en XAML. Debe ejecutarse antes de acceder a los controles con x:Name. AppShell.xaml organiza las páginas de Shell, mientras MauiProgram.cs configura la aplicación. Los .csproj de los proyectos enviados utilizan destinos net10.0: los ejemplos originales pueden contener nombres de API anteriores. No cambies el framework para estudiar un fragmento aislado.'])
    ],
    pitfalls: ['Confundir instalar una imagen con crear un dispositivo virtual.', 'Copiar solo el XAML sin su code-behind o sin ajustar x:Class.', 'Considerar las capturas de API 34 una prescripción para todos los equipos.'],
    practice: { title: 'Comprobación del material de configuración', prompt: 'Abre ConfiguracionMAUI.pdf y localiza las capturas del SDK Manager y del Device Manager. Después, en uno de los proyectos MSLearn, identifica la página, su code-behind y su llamada a InitializeComponent().', steps: ['Reconoce qué herramientas aparecen en el SDK Manager.', 'Distingue la imagen Android del dispositivo que la utiliza.', 'Relaciona x:Class con la clase parcial en C#.'], solution: 'El SDK Manager gestiona los componentes y las imágenes. El Device Manager define los dispositivos que se ejecutan. La declaración x:Class de una página y la clase partial de su .xaml.cs deben nombrar la misma clase; InitializeComponent carga los controles declarados.' },
    checks: ['Puedo explicar SDK frente a dispositivo virtual.', 'Sé dónde está la interfaz y dónde están sus eventos.'],
    quizzes: [quiz('¿Qué herramienta crea el dispositivo virtual, según el PDF?', ['Android Device Manager', 'Android SDK Manager', 'El archivo MainPage.xaml'], 0, 'El SDK Manager gestiona paquetes. El Device Manager crea los dispositivos para probar las aplicaciones.')]
  },
  {
    id: 'xaml-layouts', unit: 'UD2', title: 'XAML y disposición de controles', tag: 'Fundamentos', minutes: 35,
    summary: 'Lee el árbol visual y distingue StackLayout de Grid para resolver las relaciones 1 y 2.',
    sources: ['Relacion01_MAUI', 'Relacion02_MAUI', 'MSLearn02DisenioIUJesusCG', 'LECCIONES MSLEARN.md'],
    goals: ['Relacionar atributos XAML con propiedades C#.', 'Elegir disposición vertical, horizontal o por filas y columnas.'],
    sections: [
      section('1. XAML describe objetos, no dibuja coordenadas', ['ContentPage es la página que contiene la interfaz. Dentro se dispone un contenedor que organiza los controles hijos. Label muestra texto, Entry recibe texto y Button dispara una acción. Un atributo como Text asigna una propiedad; x:Name permite usar el control desde el code-behind.', 'La relación 1 pide dos distribuciones de un mismo formulario. Cambiar la disposición no debería cambiar las restricciones del usuario. Piensa en el árbol: una columna principal puede contener una fila y esa fila puede tener etiqueta y entrada. Usa las imágenes del PDF para reproducir el aspecto pedido; el texto extraído no conserva las capturas.'], '<VerticalStackLayout Padding="20" Spacing="10">\n    <Label Text="Nombre" />\n    <Entry x:Name="NombreEntry" MaxLength="20" />\n    <Button Text="Acceder" Clicked="Acceder_Clicked" />\n    <Label x:Name="ResultadoLabel" />\n</VerticalStackLayout>', 'xml', 'Fragmento XAML: controles del formulario'),
      section('2. StackLayout: una dirección cada vez', ['StackLayout ordena los hijos según Orientation. En vertical los coloca uno debajo de otro; en horizontal, uno junto al siguiente. VerticalStackLayout y HorizontalStackLayout expresan esas direcciones directamente, como en los proyectos MSLearn recibidos.', 'La relación 2 exige una versión usando solo StackLayout. Para esa entrega, utiliza StackLayout con Orientation="Vertical" en la raíz y varios StackLayout con Orientation="Horizontal" para las filas de botones. No sustituyas esa condición por Grid aunque resulte más cómodo. Las cuatro versiones del ejercicio deben conservar el comportamiento de la calculadora.']),
      section('3. Grid: filas y columnas compartidas', ['Grid permite que los controles compartan filas y columnas. Auto reserva lo que necesita el contenido; * reparte el espacio disponible. Grid.Row y Grid.Column empiezan en cero. Grid.ColumnSpan permite que el visor ocupe todas las columnas sin crear otra fila de contenedores.', 'La segunda versión de la calculadora usa Grid. Antes de escribir botones, cuenta filas y columnas en la imagen del PDF. Define primero la estructura y asigna después las posiciones. Un control sin posición explícita acaba inicialmente en la celda 0,0, de modo que varios controles pueden superponerse.'], '<Grid RowDefinitions="Auto,*" ColumnDefinitions="*,*"\n      RowSpacing="8" ColumnSpacing="8">\n    <Entry Grid.Row="0" Grid.ColumnSpan="2" IsReadOnly="True" />\n    <Button Grid.Row="1" Grid.Column="0" Text="1" />\n    <Button Grid.Row="1" Grid.Column="1" Text="2" />\n</Grid>', 'xml', 'Fragmento de estructura: no es la calculadora completa'),
      section('4. Espaciado y propiedades en los ejemplos Learn', ['Margin deja espacio fuera de un elemento; Padding reserva espacio dentro del contenedor que lo soporta; Spacing separa hijos en los contenedores de pila. No son intercambiables. HorizontalOptions y VerticalOptions controlan cómo se coloca un hijo dentro del espacio que su padre le ofrece.', 'Los proyectos Learn incluyen botones Start, Center, End y Fill con manejadores centralizados. Identifican el botón mediante sender y cambian las opciones del control target. También contienen Slider y etiquetas para propina: sirven para observar controles y eventos, no añaden una nueva relación al temario.']),
      section('5. Label, Entry y Button: las referencias del listado', ['El listado de UD2 enlaza las referencias de estos tres controles. Label presenta información mediante Text; puedes configurar FontSize, TextColor y alineación del texto. La alineación del texto dentro de una Label no equivale a colocar la Label dentro de su padre: son niveles distintos de la interfaz.', 'Entry introduce una línea de texto. Text es el dato; Placeholder es una indicación cuando está vacío. IsPassword oculta la representación del texto, pero no lo valida; IsReadOnly impide editarlo; MaxLength limita la introducción y Keyboard sugiere un teclado. Ninguna de estas propiedades sustituye las reglas del modelo.', 'Button comunica una acción mediante Clicked. El nombre del método en XAML debe existir en el code-behind con firma compatible. sender identifica el objeto que disparó el evento; EventArgs contiene la información del evento. Un manejador compartido puede distinguir los botones sin duplicar toda la lógica.']),
      section('6. BoxView y Slider: los otros controles de UD2', ['BoxView representa un rectángulo de color. Su propiedad Color define el color y WidthRequest y HeightRequest solicitan dimensiones. No es un contenedor de controles. La referencia de BoxView está en el listado recibido; en las prácticas puede ayudar a entender que un View no siempre recibe texto o pulsaciones.', 'Slider permite escoger un valor double en un intervalo continuo, definido por Minimum y Maximum; Value es la posición actual. ValueChanged informa del cambio y proporciona NewValue. En InterfazGrid.xaml del RAR MSLearn aparece tipPercentSlider con Minimum=0, Maximum=100 y Value=15. El nombre del archivo no garantiza el layout: el contenido recibido de ese archivo usa VerticalStackLayout.', 'Distingue número y texto: Slider.Value es un número, mientras Label.Text es una cadena. Para mostrar el porcentaje debes convertirlo a una representación textual. Estudia cómo se actualiza el resultado al cambiar el dato, sin convertir este ejemplo Learn en una nueva relación inventada.'])
    ],
    pitfalls: ['Usar índices de Grid empezando en 1.', 'Cambiar la lógica al cambiar el layout.', 'Entregar Grid donde el enunciado exige solo StackLayout.'],
    practice: { title: 'Relación 1 · dos presentaciones', prompt: 'Reproduce las dos interfaces de acceso de Relacion01_MAUI.pdf utilizando las imágenes originales como referencia. Ambas solicitan nombre, apellidos y edad.', steps: ['Mira las dos capturas del PDF.', 'Separa disposición visual y validación.', 'Mantén el mismo resultado para los mismos datos en ambas versiones.'], solution: 'Las dos pantallas recogen los mismos datos y aplican las mismas restricciones. La diferencia es la composición de los contenedores. El PDF es la referencia visual; no basta con conservar solo los nombres de los campos.' },
    checks: ['Distingo Margin, Padding y Spacing.', 'Sé por qué Grid.Row="0" es la primera fila.', 'Puedo rehacer una distribución sin alterar su validación.'],
    quizzes: [quiz('¿Qué exige la primera interfaz de la calculadora en la relación 2?', ['Usar solo StackLayout para disponer los Views', 'Usar obligatoriamente Grid', 'Crear un ContentView personalizado'], 0, 'La relación 2 pide primero ContentPage con solo StackLayout, luego Grid, y después ambas versiones en C#. ')]
  },
  {
    id: 'formulario', unit: 'UD2', title: 'Relación 1 · formulario y validación', tag: 'Relación 01', minutes: 45,
    summary: 'Aplica los límites exactos del enunciado y separa los datos de la respuesta visual.',
    sources: ['Relacion01_MAUI', 'Relacion1E01_JesusCG'],
    goals: ['Validar nombre, apellidos y edad con los límites originales.', 'Entender POO, excepciones y retroalimentación al usuario.'],
    sections: [
      section('1. Convertir el enunciado en comprobaciones', ['Nombre: entre 3 y 20 caracteres, ambos incluidos. Apellidos: entre 4 y 40. Edad: entre 5 y 70 años. Los tres datos son obligatorios. Ser menor de 18 no convierte la edad en un dato inválido: si tiene entre 5 y 17, el resultado es “No tiene acceso al sistema”.', 'El botón Acceder muestra el mensaje en una etiqueta cuando los datos son correctos. Los errores se comunican mediante DisplayAlert(), según el PDF. En .NET MAUI 10 el nombre actualizado es DisplayAlertAsync(); los proyectos y el enunciado no son siempre de la misma revisión de API. La idea evaluada es tratar el error y comunicarlo.']),
      section('2. Qué aporta el modelo de datos', ['El enunciado pide POO para el modelo. En el RAR, DataModelR1_JesusCG contiene Usuario.cs: la propiedad Nombre valida en el setter y protege su lectura si no se ha establecido. Esto ilustra que el dato se comprueba antes de almacenarlo.', 'Ese archivo recibido solo implementa Nombre. No es una solución completa de todos los requisitos de la relación: aún deben contemplarse apellidos, edad y la interfaz. La página recoge entradas, el modelo aplica reglas y la página decide cómo mostrar el resultado. No atribuyas al archivo comprobaciones que no contiene.']),
      section('3. Ordenar el manejador del botón', ['Primero recoge y convierte la edad; después valida los límites de los datos y finalmente muestra la respuesta. Keyboard="Numeric" ayuda a introducir números, pero no garantiza que Entry.Text sea un entero válido. Una conversión fallida debe producir una explicación y no cerrar la aplicación.', 'Este fragmento muestra el flujo de la página. Presupone controles con esos nombres y el resto de la clase de página creado. La lógica es una explicación del enunciado, no un archivo original del profesor.'], 'private async void Acceder_Clicked(object sender, EventArgs e)\n{\n    try\n    {\n        string nombre = (NombreEntry.Text ?? "").Trim();\n        string apellidos = (ApellidosEntry.Text ?? "").Trim();\n        if (nombre.Length < 3 || nombre.Length > 20)\n            throw new ArgumentException("Nombre: entre 3 y 20 caracteres.");\n        if (apellidos.Length < 4 || apellidos.Length > 40)\n            throw new ArgumentException("Apellidos: entre 4 y 40 caracteres.");\n        if (!int.TryParse(EdadEntry.Text, out int edad) || edad < 5 || edad > 70)\n            throw new ArgumentException("Edad: entero entre 5 y 70.");\n\n        ResultadoLabel.Text = edad >= 18\n            ? "Tiene acceso al sistema"\n            : "No tiene acceso al sistema";\n    }\n    catch (ArgumentException ex)\n    {\n        ResultadoLabel.Text = "";\n        await DisplayAlertAsync("Datos incorrectos", ex.Message, "Aceptar");\n    }\n}', 'csharp', 'Fragmento de flujo; la entrega pide además modelo POO'),
      section('4. Comprobar las fronteras', ['Prueba justo por debajo, justo en el límite y justo por encima. Para nombre son especialmente útiles longitudes 2, 3, 20 y 21; para edad, 4, 5, 17, 18, 70 y 71. Así distingues un límite mal escrito de un fallo general.', 'La misma validación debe funcionar en las dos disposiciones. No reutilices los límites 5–15 de EntryNombreUsuario de la relación 5: son otro control y otra práctica. El texto final y el aspecto visual completo deben cotejarse con las imágenes del PDF.'])
    ],
    pitfalls: ['Rechazar a todos los menores de 18 como error de formato.', 'Confundir los límites de esta relación con los de la relación 5.', 'Dar por terminada la relación porque Usuario.cs valida Nombre.'],
    practice: { title: 'Relación 1 · acceso vertical y mixto', prompt: 'Resuelve los ejercicios 1 y 2 del PDF: solicita los tres datos, usa POO para el modelo, trata excepciones y muestra el acceso según la mayoría de edad.', steps: ['Implementa todos los límites, no solo MaxLength.', 'Valida entradas vacías y no numéricas.', 'Comprueba que 17 y 18 producen mensajes distintos sin error.'], solution: 'Datos incompletos o fuera de rango → alerta. Datos válidos con edad 5–17 → “No tiene acceso al sistema”. Datos válidos con edad 18–70 → “Tiene acceso al sistema”. El modelo debe representar las tres piezas de información; el RAR recibido permite estudiar el patrón de validación para Nombre.' },
    checks: ['Compruebo nombre 3–20 y apellidos 4–40.', 'Compruebo edad 5–70 y distingo el umbral 18.', 'Mi interfaz no conserva un éxito anterior después de un error.'],
    quizzes: [quiz('Con nombre y apellidos válidos, ¿qué ocurre con una edad de 17?', ['Es un dato válido, pero no tiene acceso', 'La edad es inválida porque es menor de 18', 'Tiene acceso porque supera los 5 años'], 0, 'La edad admitida es 5–70. El umbral de 18 decide el mensaje de acceso, no la validez del dato.')]
  },
  {
    id: 'calculadora', unit: 'UD2', title: 'Relación 2 · calculadora y eventos', tag: 'Relación 02', minutes: 60,
    summary: 'Una misma calculadora de enteros en cuatro versiones, con eventos centralizados y tratamiento de errores.',
    sources: ['Relacion02_MAUI', 'Relacion02_JesusCG'],
    goals: ['Reconstruir las cuatro versiones pedidas.', 'Entender el estado entre pulsaciones y los eventos compartidos.'],
    sections: [
      section('1. Cuatro interfaces, un comportamiento', ['El PDF pide: ContentPage XAML con StackLayout, ContentPage XAML con Grid, ContentPage C# con StackLayout y ContentPage C# con Grid. Todas usan un Entry de solo lectura como visor. El usuario introduce números mediante los botones, no escribiendo directamente sobre el visor.', 'Los eventos son centralizados: varios dígitos se conectan al mismo método, y ese método obtiene el botón con sender. Esto evita un método casi idéntico para cada tecla. Los operadores pueden compartir otro manejador. Revisa las posiciones y teclas de la imagen original antes de montar cada versión.']),
      section('2. Estado: qué debes recordar entre dos clics', ['Una pulsación aislada no contiene toda la operación. Después de introducir el primer entero y pulsar un operador, guarda el primer operando y el operador, cambia a la fase del segundo operando y limpia el visor. Al pulsar igual, convierte el segundo operando y calcula.', 'Ejercicio02.xaml.cs recibido usa TipoEstado con Operando1 y Operando2. Es un patrón que puedes seguir, pero comprueba qué ocurre después de mostrar el resultado: el original no restablece explícitamente ese estado en la rama de éxito. Debes decidir y probar el comportamiento que mantiene coherencia al comenzar la siguiente operación.'], 'private void DigitosClick(object sender, EventArgs e)\n{\n    if (sender is Button boton)\n        eVisor.Text += boton.Text;\n}', 'csharp', 'Fragmento explicado del manejador centralizado'),
      section('3. Cálculo entero y errores', ['Calculos.cs recibido contiene suma, resta, multiplicación, división y resto sobre int. La división entera descarta la parte fraccionaria: 7 / 2 produce 3. Dividir o calcular el resto entre cero es un error. Convertir un número fuera del rango de int también debe gestionarse.', 'El switch original deja resultado en cero si llega un operador desconocido. Para estudiar el flujo, distingue un resultado matemático cero de una operación no admitida. El siguiente fragmento hace explícitos los errores y usa checked para detectar desbordamiento; es una explicación alternativa del mismo cálculo, no el código del RAR.'], 'static int Calcular(int a, int b, char operador) => operador switch\n{\n    \'+\' => checked(a + b),\n    \'-\' => checked(a - b),\n    \'*\' => checked(a * b),\n    \'/\' => a / b,\n    \'%\' => a % b,\n    _ => throw new ArgumentException("Operador no válido")\n};', 'csharp', 'Fragmento didáctico: cálculo de enteros'),
      section('4. La versión en C# sigue siendo una interfaz MAUI', ['En C# creas objetos Entry, Button, StackLayout o Grid y asignas propiedades. Después añades hijos y suscribes eventos. Content debe recibir el contenedor raíz; crear los controles sin añadirlos al árbol no los hace visibles.', 'En XAML, Clicked="DigitosClick" declara la conexión. En C#, la equivalente es boton.Clicked += DigitosClick. La lógica puede conservar los mismos métodos en ambos casos. Verifica también el reinicio tras error, igual sin operación, operador repetido y un segundo operando vacío. El PDF exige excepciones y alertas, no solo la pantalla.'])
    ],
    pitfalls: ['Tener un manejador diferente para cada dígito.', 'Olvidar IsReadOnly en el visor.', 'No reiniciar estado o no comprobar división por cero.', 'Esperar decimales de una calculadora de enteros.'],
    practice: { title: 'Relación 2 · las cuatro versiones', prompt: 'Reproduce la calculadora de la imagen en las cuatro variantes que especifica el PDF. Mantén el visor de solo lectura, los eventos centralizados y el tratamiento de excepciones con alerta.', steps: ['Construye la disposición Stack XAML y Grid XAML.', 'Repite el árbol visual con objetos C# para Stack y Grid.', 'Comprueba operación válida, igual prematuro, operador repetido y cero como divisor.'], solution: 'Las cuatro variantes cambian cómo se construye el árbol visual, no qué calcula. El manejador de dígitos acumula texto; el de operaciones conserva primer entero y operador, recoge el segundo y llama al cálculo. Tras un error se informa y se devuelve la calculadora a un estado coherente. Consulta las fuentes recibidas en la biblioteca y sus limitaciones explicadas arriba.' },
    checks: ['Tengo las cuatro páginas exigidas.', 'El visor es de solo lectura y los eventos compartidos.', 'Puedo hacer una nueva operación después de un resultado o un error.'],
    quizzes: [quiz('En la calculadora de enteros recibida, ¿cuánto vale 7 / 2?', ['3', '3,5', 'No se permite dividir números impares'], 0, 'Ambos operandos son int. La división es entera y descarta la parte fraccionaria.')]
  },
  {
    id: 'tablero', unit: 'UD2', title: 'Relación 3 · tablero dinámico 5 × 5', tag: 'Relación 03', minutes: 45,
    summary: 'Genera 25 botones en C# y conserva el ciclo de color de cada uno.',
    sources: ['Relacion03_MAUI', 'Relacion03E02_JesusCG'],
    goals: ['Crear la interfaz al iniciar la aplicación.', 'Separar el estado de cada botón del estado de la página.'],
    sections: [
      section('1. De una tabla a dos índices', ['El ejercicio 1 exige generar por código una matriz 5×5 de botones numerados de 1 a 25. Se permite StackLayout, Grid o una combinación. No basta con escribir 25 botones en XAML: la generación en tiempo de ejecución es parte explícita del enunciado.', 'Con Grid, fila y columna van de 0 a 4. El texto del botón es fila * 5 + columna + 1. La primera celda muestra 1 y la última 25. Cada botón se añade al Grid y todos pueden compartir un manejador que lea el botón pulsado.'], 'public class Ejercicio01 : ContentPage\n{\n    public Ejercicio01()\n    {\n        Grid grid = new Grid { RowSpacing = 5, ColumnSpacing = 5 };\n        for (int i = 0; i < 5; i++)\n        {\n            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Star });\n            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Star });\n        }\n        for (int fila = 0; fila < 5; fila++)\n        for (int columna = 0; columna < 5; columna++)\n        {\n            Button boton = new Button { Text = (fila * 5 + columna + 1).ToString() };\n            boton.Clicked += Pulsado;\n            grid.Add(boton, columna, fila);\n        }\n        Content = grid;\n    }\n\n    private async void Pulsado(object? sender, EventArgs e)\n    {\n        if (sender is Button boton)\n            await DisplayAlertAsync("Tablero", $"Has pulsado el botón {boton.Text}", "Aceptar");\n    }\n}', 'csharp', 'Ejemplo didáctico de página C# · dentro de tu namespace'),
      section('2. El ciclo de color pertenece a cada botón', ['El ejercicio 2 cambia el fondo: primera pulsación verde, segunda roja, tercera vuelve al original. Debes recordar el estado individual de cada botón; un contador compartido por toda la página haría que pulsar uno alterase el siguiente paso de otro.', 'El RAR contiene MiBoton.cs, que hereda de Button y guarda un enum Azul, Verde, Rojo. Su constructor fija el color original en azul y suscribe el evento. Al pulsar alterna entre esos tres estados. Para el enunciado general, “original” significa el fondo inicial de ese botón: en ese archivo concreto es azul. No confundas ese detalle de la solución recibida con una obligación de fondo azul para cualquier implementación.']),
      section('3. Verificar dos botones, no solo uno', ['Pulsa el botón 1 una vez y el 2 una vez: los dos deben estar verdes. Pulsa el 1 de nuevo: solo él pasa a rojo. Después, el tercer clic sobre el 1 lo devuelve a su color original.', 'En la primera versión, el mensaje debe identificar la numeración que ve el usuario. Leer sender.Text evita capturar por error una variable de bucle que ya ha cambiado cuando se dispara el evento. La segunda versión debe conservar la generación dinámica pedida para la interfaz anterior.'])
    ],
    pitfalls: ['Generar 24 o 26 botones por un límite de bucle incorrecto.', 'Intercambiar fila y columna al añadir al Grid.', 'Compartir un único estado de color entre todos los botones.'],
    practice: { title: 'Relación 3 · dos tableros', prompt: 'Crea Ejercicio01.cs con la matriz dinámica y su alerta. Crea Ejercicio02.cs con el ciclo de colores del enunciado.', steps: ['Genera exactamente 25 botones al arrancar.', 'Verifica que los mensajes corresponden a 1 y 25.', 'Comprueba independencia del color pulsando alternativamente dos botones.'], solution: 'El tablero puede construirse con dos bucles de cinco iteraciones. Cada botón recibe número y posición. La segunda versión necesita estado por botón, como el campo privado de MiBoton.cs del RAR; el ciclo requerido es original → verde → rojo → original.' },
    checks: ['Hay 25 botones creados por C#.', 'Cada clic identifica el número correcto.', 'El ciclo es independiente en cada botón.'],
    quizzes: [quiz('¿Qué ocurre en la tercera pulsación sobre el mismo botón en la relación 3?', ['Recupera el fondo original', 'Permanece rojo', 'Se elimina del tablero'], 0, 'El enunciado define verde en la primera pulsación, rojo en la segunda y el fondo original en la tercera.')]
  },
  {
    id: 'navegacion', unit: 'UD2', title: 'Relación 4 · navegación flotante', tag: 'Relación 04', minutes: 35,
    summary: 'Reúne las páginas anteriores respetando los títulos de menú de la relación.',
    sources: ['Relacion04_MAUI', 'LECCIONES MSLEARN.md'],
    goals: ['Organizar páginas con Shell y menú lateral.', 'Conservar el funcionamiento de las prácticas al integrarlas.'],
    sections: [
      section('1. Qué hay que integrar', ['La relación propone tres aplicaciones en la misma solución. La primera reúne Acceso Vertical y Acceso Mixto de la relación 1. La segunda reúne las cuatro calculadoras de la relación 2. La tercera reúne Tablero Dinámico y Tablero Dinámico Color de la relación 3.', 'No se trata de reescribir las prácticas: el trabajo es integrar páginas existentes en una navegación flotante. Los nombres de páginas del PDF son AccesoVertical.xaml, AccesoMixto.xaml, CalculadoraStackX.xaml, CalculadoraGridX.xaml, CalculadoraStackCS.cs, CalculadoraGridCS.cs, TableroCS.cs y TableroColorCS.cs.']),
      section('2. Declarar destinos en Shell', ['Los enlaces Learn del profesor incluyen creación de aplicaciones multipágina. Shell permite declarar destinos y un menú lateral. En este fragmento, cada FlyoutItem contiene un ShellContent cuya plantilla crea la página correspondiente. El prefijo local debe apuntar al namespace real de tus páginas.', 'Si copias una página a otro proyecto, actualiza x:Class y el namespace de su .xaml.cs juntos. Importa también las clases de modelo y controles que use. Una página que compila aislada puede fallar al integrarse si no has añadido una referencia a su biblioteca.'], '<Shell xmlns="http://schemas.microsoft.com/dotnet/2021/maui"\n       xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"\n       xmlns:local="clr-namespace:TuProyecto"\n       x:Class="TuProyecto.AppShell" FlyoutBehavior="Flyout">\n    <FlyoutItem Title="Acceso Vertical">\n        <ShellContent ContentTemplate="{DataTemplate local:AccesoVertical}" />\n    </FlyoutItem>\n    <FlyoutItem Title="Acceso Mixto">\n        <ShellContent ContentTemplate="{DataTemplate local:AccesoMixto}" />\n    </FlyoutItem>\n</Shell>', 'xml', 'Ejemplo didáctico AppShell.xaml · adaptar TuProyecto'),
      section('3. Verificar la integración', ['Abre cada destino desde el menú y comprueba que su interfaz no aparece duplicada dentro de otra ContentPage. Shell aloja páginas; no copies una ContentPage completa como hijo visual de otra página.', 'Comprueba también la lógica: los formularios siguen mostrando sus mensajes, las calculadoras siguen gestionando errores y los tableros siguen generándose. El enunciado no pide inventar páginas extra ni una nueva lógica de negocio.'])
    ],
    pitfalls: ['Mantener un x:Class antiguo al mover la página.', 'Olvidar la biblioteca del modelo o los controles.', 'Confundir el título del menú con el nombre de la clase.'],
    practice: { title: 'Relación 4 · integrar lo ya hecho', prompt: 'Crea las tres aplicaciones con navegación flotante que enumera el PDF, usando los ejercicios de las relaciones 1, 2 y 3.', steps: ['App 1: Acceso Vertical y Acceso Mixto.', 'App 2: las cuatro calculadoras.', 'App 3: ambos tableros dinámicos.'], solution: 'Los destinos del menú deben corresponder a páginas reales con sus dependencias. Conserva los títulos del PDF y comprueba cada destino. El patrón Shell anterior muestra las dos entradas de la primera aplicación; las otras dos siguen la misma organización con sus páginas correspondientes.' },
    checks: ['Se abren los ocho destinos repartidos en tres aplicaciones.', 'Cada destino mantiene la lógica de su relación.', 'Los títulos coinciden con el PDF.'],
    quizzes: [quiz('¿Qué integra la tercera aplicación de la relación 4?', ['Los dos tableros de la relación 3', 'Los dos formularios de la relación 1', 'Las cuatro calculadoras de la relación 2'], 0, 'La tercera aplicación reúne Tablero Dinámico y Tablero Dinámico Color.')]
  },
  {
    id: 'especializacion', unit: 'UD2', title: 'Relación 5 · especializar Views', tag: 'Relación 05', minutes: 50,
    summary: 'Usuario de 5–15 letras y contraseña de 10 caracteres: reglas, biblioteca y diferencias con el código recibido.',
    sources: ['Relacion05_MAUI', 'Relacion05_JesusCG', 'Relacion03E02_JesusCG'],
    goals: ['Distinguir herencia de Entry y composición con ContentView.', 'Aplicar exactamente las restricciones del PDF.'],
    sections: [
      section('1. El contrato lo fija el enunciado', ['EntryNombreUsuario debe basarse en Entry. La longitud admitida es 5–15 y no puede incluir acentos, signos de puntuación, dígitos ni otros caracteres especiales. La contraseña debe ocultarse y medir exactamente 10 caracteres, con al menos una minúscula, una mayúscula, un dígito y un signo de puntuación de los indicados: punto, coma, dos puntos o punto y coma.', 'No mezcles estas longitudes con las de la relación 1. MaxLength limita lo que se introduce manualmente, pero por sí solo no valida la longitud mínima, el conjunto de caracteres o todos los valores que un programa puede asignar. La regla debe comprobarse cuando se usa el dato.']),
      section('2. Especializar y componer son cosas distintas', ['Heredar de Entry significa que el nuevo tipo sigue siendo un Entry y añade un comportamiento propio. ContentView, en cambio, puede contener un Entry y una Label de error. En el RAR de relación 5, las clases EntryNombreUsuario y EntryContrasenia heredan de ContentView, aunque su nombre empiece por Entry. Es una diferencia real con la redacción del PDF.', 'Estudia ese código para entender composición y retroalimentación, pero usa el PDF para saber qué pide cada ejercicio. En la relación 6 se exige expresamente componer mediante ContentView; la relación 5 habla de especializar los controles. La biblioteca se importa desde una aplicación de prueba, no se ejecuta por sí sola.']),
      section('3. Validación y diferencias detectadas', ['El código recibido valida usuario con Char.IsLetter, que admite letras con acento. Por tanto, esa comprobación sola no cumple la prohibición expresa de acentos del PDF. Además, el método ValidarUsuario no comprueba el máximo; la interfaz lo limita mediante MaxLength, lo que no sustituye una validación completa del valor.', 'La contraseña recibida usa Char.IsPunctuation, una categoría más amplia que los cuatro signos listados. El fragmento siguiente expresa una lectura estricta de los caracteres especificados, sin añadir nuevos requisitos. La exclusión de ñ no está aclarada por el PDF: el ejemplo de usuario usa el alfabeto A–Z/a–z; si el profesor admite ñ, esa parte requiere su criterio.'], 'static bool UsuarioValido(string? valor) =>\n    valor is not null && valor.Length >= 5 && valor.Length <= 15\n    && valor.All(c => (c >= \'A\' && c <= \'Z\') || (c >= \'a\' && c <= \'z\'));\n\nstatic bool PasswordValida(string? valor) =>\n    valor is not null && valor.Length == 10\n    && valor.Any(char.IsLower) && valor.Any(char.IsUpper)\n    && valor.Any(char.IsDigit)\n    && valor.Any(c => ".,:;".Contains(c));', 'csharp', 'Fragmento de validación · requiere System.Linq'),
      section('4. No depender exclusivamente de perder el foco', ['El RAR valida en Unfocused y muestra el error en una etiqueta. Pero la aplicación también debe comprobar el dato cuando pulsa el botón que lo utiliza. El usuario podría pulsar sin haber pasado antes por el campo o sin haber disparado la secuencia de foco que esperabas.', 'La segunda parte pide crear LoginAcceso, importar la biblioteca y mostrar un Alert con los datos introducidos para probarla. Esa visualización de contraseña forma parte de la práctica recibida; no convierte el control en un sistema de autenticación. No hay servidor de usuarios en el material.'])
    ],
    pitfalls: ['Suponer que Char.IsLetter excluye acentos.', 'Creer que el nombre de clase Entry implica que hereda de Entry.', 'Validar solo al perder el foco.', 'Comprobar longitud mínima 10 en lugar de longitud exacta 10 para contraseña.'],
    practice: { title: 'Relación 5 · biblioteca y aplicación de prueba', prompt: 'Implementa los dos Views con las reglas originales, genera la biblioteca MAUI e impórtala en LoginAcceso. Añade el botón y la alerta de prueba que exige el documento.', steps: ['Usuario: prueba 4, 5, 15 y 16 caracteres y caracteres prohibidos.', 'Contraseña: prueba longitud 9, 10 y 11; elimina una categoría cada vez.', 'Comprueba lectura del dato desde la aplicación anfitriona.'], solution: 'La biblioteca contiene la validación de los controles. El anfitrión los referencia y utiliza sus datos. Contrasta los archivos originales: las implementaciones recibidas son ContentView y aceptan categorías de caracteres más amplias que el texto del enunciado; no las copies suponiendo que resuelven todas sus condiciones.' },
    checks: ['Usuario cumple 5–15 y la restricción de caracteres.', 'Contraseña oculta, longitud 10 y cuatro categorías.', 'Distingo PDF y particularidades del RAR.'],
    quizzes: [quiz('¿Qué longitud exige el PDF para la contraseña?', ['Exactamente 10', 'Entre 5 y 15', 'Al menos 10'], 0, 'El PDF indica un tamaño de 10 caracteres, además de las categorías de caracteres que enumera.')]
  },
  {
    id: 'contentview', unit: 'UD2', title: 'Relación 6 · componer LoginView', tag: 'Relación 06', minutes: 40,
    summary: 'Une los controles de la relación 5 y expón UserName y PassWord desde un ContentView.',
    sources: ['Relacion06_MAUI', 'Relacion05_JesusCG', 'LECCIONES MSLEARN.md'],
    goals: ['Componer un control reutilizable sin duplicar validaciones.', 'Exponer las propiedades con los nombres del enunciado.'],
    sections: [
      section('1. Un control que agrupa controles', ['La relación 6 pide un nuevo LoginView basado en ContentView que contenga EntryNombreUsuario y EntryContrasenia de la relación 5. El nuevo control ofrece una unidad reutilizable: la aplicación lo coloca y no necesita conocer cómo están distribuidos sus elementos internos.', 'La biblioteca se llama BAcceso_<Alumn@>. La aplicación de prueba LoginAccesoV2_<Alumn@> importa la biblioteca y muestra mediante un botón los datos del View. La composición no elimina las reglas de los controles hijos ni las vuelve a definir con límites distintos.']),
      section('2. Exponer información sin exponer los campos internos', ['El enunciado nombra UserName y PassWord. Puedes exponer propiedades de lectura que deleguen en la API validada de los controles contenidos. No devuelvas directamente cualquier texto interno si con ello evitas la comprobación que ya hiciste en los hijos.', 'El siguiente fragmento usa los nombres de las clases y propiedades del RAR de relación 5: Usuario y Password. Si especializas Entry en tu propia versión, adapta esas dos lecturas a la API de tus controles. El namespace y la referencia a la biblioteca deben existir en tu solución.'], 'public partial class LoginView : ContentView\n{\n    public LoginView()\n    {\n        InitializeComponent();\n    }\n\n    public string UserName => UsuarioView.Usuario;\n    public string PassWord => PasswordView.Password;\n}', 'csharp', 'Fragmento LoginView.xaml.cs · UsuarioView y PasswordView son x:Name'),
      section('3. Conectar la biblioteca con XAML', ['En el XAML del ContentView declara el prefijo que apunta a la biblioteca hija y añade ambos controles dentro del contenedor. Si están en otro ensamblado, xmlns necesita clr-namespace y assembly. El nombre del ensamblado no es una ruta de disco ni el nombre de un archivo .xaml.', 'En el anfitrión coloca LoginView con x:Name y lee UserName y PassWord al pulsar el botón. Trata las excepciones que puedan producir las lecturas validadas. Inicializa los componentes antes de acceder a los hijos. No necesitas otra página de autenticación ni un almacenamiento de contraseñas para esta relación.'], '<!-- Fragmento dentro de LoginView.xaml; ajustar namespace y assembly -->\n<ContentView xmlns="http://schemas.microsoft.com/dotnet/2021/maui"\n             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"\n             xmlns:views="clr-namespace:BLoginViews_JesusCG;assembly=BLoginViews_JesusCG"\n             x:Class="BAcceso.LoginView">\n    <VerticalStackLayout Spacing="10">\n        <views:EntryNombreUsuario x:Name="UsuarioView" />\n        <views:EntryContrasenia x:Name="PasswordView" />\n    </VerticalStackLayout>\n</ContentView>', 'xml', 'Ejemplo de composición · ajustar proyecto BAcceso'),
      section('4. Biblioteca, ensamblado y referencia de proyecto', ['Los enlaces de UD3-4 incluyen bibliotecas de clases y su creación en Visual Studio. La biblioteca reúne tipos reutilizables y su compilación genera un ensamblado. No tiene una pantalla principal que se lance como una aplicación. La aplicación anfitriona debe referenciar la biblioteca y usar sus tipos públicos.', 'Una clase C# de modelo puede vivir en una biblioteca sin controles visuales; una biblioteca que usa Entry o ContentView necesita la configuración y referencias de MAUI apropiadas. Para estas relaciones sigue el tipo de biblioteca MAUI pedido en los PDF y los .csproj de ejemplo. No basta con copiar el .dll sin sus dependencias ni con escribir un xmlns si no hay referencia al proyecto.']),
      section('5. Image: otro View del listado de UD3-4', ['El profesor incluye la referencia de Image. Es un View que muestra una imagen a partir de Source. La propiedad Aspect regula cómo se adapta al espacio: AspectFit mantiene la imagen completa y su proporción; AspectFill conserva proporción pero puede recortar; Fill adapta a las dimensiones y puede deformar.', 'Image no es una ContentPage ni un ContentView: es un control que puedes colocar dentro de un contenedor. La referencia está disponible en el listado original. No se ha añadido un ejercicio de imágenes porque los enunciados enviados no lo piden.'])
    ],
    pitfalls: ['Usar un namespace de otra solución sin referencia de proyecto.', 'Copiar la validación en tres sitios y dejar reglas distintas.', 'Leer datos sin comprobar errores de los controles hijos.'],
    practice: { title: 'Relación 6 · LoginAccesoV2', prompt: 'Crea BAcceso con LoginView, integra los dos Views anteriores y publica UserName y PassWord. Importa el nuevo View en la aplicación de prueba pedida.', steps: ['La biblioteca referencia los controles de la relación 5.', 'LoginView compone ambos controles.', 'La aplicación puede obtener datos válidos y recibe retroalimentación cuando no lo son.'], solution: 'El ContentView reúne la presentación y delega las reglas en los controles hijos. Sus propiedades públicas permiten al anfitrión acceder a la información sin manipular directamente las entradas internas. Las propiedades simples resuelven la lectura pedida; la personalización de propiedades en relaciones posteriores requiere mecanismos adicionales.' },
    checks: ['He creado un ContentView, no una ContentPage.', 'La API ofrece UserName y PassWord.', 'La aplicación anfitriona usa el control y trata sus errores.'],
    quizzes: [quiz('¿Qué clase base pide expresamente LoginView en la relación 6?', ['ContentView', 'ContentPage', 'Shell'], 0, 'La relación pide componer los Views anteriores en un ContentView reutilizable.')]
  },
  {
    id: 'extensiones', unit: 'UD3-4', title: 'Relación 7 · extensiones XAML', tag: 'Relación 07 · A', minutes: 45,
    summary: 'IMarkupExtension, x:Static y valores distintos según plataforma y tipo de View.',
    sources: ['Relacion07_MAUI_2627', 'LECCIONES MSLEARN.md'],
    goals: ['Distinguir una extensión propia de una referencia estática.', 'Aplicar las cinco propiedades enumeradas en el PDF.'],
    sections: [
      section('1. Qué pide la primera actividad', ['Debes modificar los Views de las relaciones 5 y 6. Las propiedades son espaciado, relleno, margen, color de fondo y tamaño de fuente. Deben existir valores diferentes para Windows y Android, y valores distintos según tipo de View cuando corresponda.', 'El PDF exige hacerlo de dos maneras: clases propias que implementen IMarkupExtension y la clase por defecto StaticExtension. En XAML, x:Static es la forma habitual de usar StaticExtension. No significa StaticResource: una referencia a un miembro estático y una búsqueda en un diccionario de recursos son mecanismos distintos.']),
      section('2. Una extensión devuelve un valor del tipo adecuado', ['Una extensión de marcado calcula o proporciona el valor que recibirá una propiedad. ProvideValue recibe información de servicios y devuelve el valor. Para Spacing se necesita un número; para Padding o Margin, Thickness; para BackgroundColor, Color. No reutilices una extensión que devuelve double como si devolviera un color.', 'El fragmento siguiente usa el valor 10 exigido después en la relación 8, por eso no introduce una cifra arbitraria. Para la relación 7 el PDF no fija cifras concretas: sí exige que se diferencien según plataforma y View. La anotación AcceptEmptyServiceProvider corresponde a las extensiones de MAUI 10 que no usan servicios.'], 'using Microsoft.Maui.Controls.Xaml;\n\n[AcceptEmptyServiceProvider]\npublic class EspaciadoExtension : IMarkupExtension<double>\n{\n    public double ProvideValue(IServiceProvider serviceProvider) => 10d;\n    object IMarkupExtension.ProvideValue(IServiceProvider serviceProvider)\n        => ProvideValue(serviceProvider);\n}', 'csharp', 'Ejemplo didáctico de extensión · valor de relación 8'),
      section('3. x:Static apunta a un miembro accesible', ['Define una clase con miembros públicos estáticos y referencia un miembro desde XAML. Si necesitas elegir Windows o Android, una propiedad estática puede consultar DeviceInfo.Current.Platform y devolver el valor previsto. La extensión no cambia sola porque el nombre sea Static: entrega el valor del miembro que has indicado.', 'El código que uses debe conservar el tipo esperado por la propiedad destino. El siguiente ejemplo vuelve a emplear únicamente los valores del enunciado de la relación 8. Para resolver la relación 7 debes además diferenciar los valores de plataforma y tipo de View, tal como exige el PDF.'], 'public static class Valores\n{\n    public static double Espaciado => 10d;\n    public static Thickness Relleno => new Thickness(10);\n    public static Color FondoMatricula => Colors.Green;\n    public static Color FondoEdad => Colors.Blue;\n}\n\n// En XAML, con xmlns:local apuntando a esta clase:\n// Spacing="{x:Static local:Valores.Espaciado}"\n// Padding="{x:Static local:Valores.Relleno}"', 'csharp', 'Fragmento de miembros estáticos y consumo XAML'),
      section('4. DeviceInfo y selección de plataforma', ['El enlace de información del dispositivo del listado UD3-4 explica DeviceInfo.Current, del namespace Microsoft.Maui.Devices. Platform identifica la plataforma; Idiom describe el tipo de dispositivo, y DeviceType distingue físico y virtual. Para la relación 7 la distinción pedida es Windows frente a Android: no se resuelve preguntando si el dispositivo es emulado.', 'Puedes comparar Platform con DevicePlatform.WinUI o DevicePlatform.Android para elegir los valores de tus extensiones. El módulo de XAML del listado UD2 también trata valores por plataforma mediante OnPlatform. El enunciado exige extensiones propias y StaticExtension, por lo que conocer OnPlatform no sustituye esas dos entregas. Los valores específicos que elijas deben poder comprobarse en ambas plataformas.'])
    ],
    pitfalls: ['Confundir x:Static con StaticResource.', 'Devolver string para una propiedad que espera Color o Thickness.', 'Olvidar las diferencias entre Windows y Android de la relación 7.'],
    practice: { title: 'Relación 7 · actividad 1', prompt: 'Personaliza los Views de las relaciones 5 y 6 mediante extensiones propias y mediante StaticExtension, cubriendo las cinco propiedades y las diferencias de plataforma y tipo de View.', steps: ['Enumera espaciado, relleno, margen, fondo y fuente.', 'Devuelve el tipo correcto en cada extensión.', 'Comprueba los valores de Windows y Android.'], solution: 'Una extensión propia implementa ProvideValue; x:Static referencia un miembro público estático. Ambos pueden proporcionar valores, pero no sustituyen el requisito de comprobar las plataformas y los tipos de View. El PDF no impone cifras para esta actividad: no hay una única tabla numérica oficial en el material enviado.' },
    checks: ['Uso IMarkupExtension y StaticExtension.', 'Cada propiedad recibe el tipo correcto.', 'He diferenciado plataformas y tipos de View.'],
    quizzes: [quiz('¿Qué referencia x:Static?', ['Un miembro público estático', 'Siempre una clave de ResourceDictionary', 'Una página de Shell'], 0, 'StaticExtension permite obtener un miembro estático; StaticResource busca un recurso por su clave.')]
  },
  {
    id: 'recursos', unit: 'UD3-4', title: 'Relación 7 · recursos y personalización', tag: 'Relación 07 · B', minutes: 50,
    summary: 'Diccionarios en ContentView, recursos estáticos, dinámicos y propiedades configurables desde el anfitrión.',
    sources: ['Relacion07_MAUI_2627', 'LECCIONES MSLEARN.md'],
    goals: ['Aplicar recursos al nivel de ContentView que pide el PDF.', 'Entender qué se actualiza al reemplazar un recurso dinámico.'],
    sections: [
      section('1. ResourceDictionary vive en un ámbito', ['La actividad 2 exige recursos a nivel de ContentView, no solamente en App.xaml. Define las claves dentro de ContentView.Resources y utiliza el tipo de cada valor. Mantén claves diferentes cuando deban existir valores distintos para Label, Entry, StackLayout o Grid.', 'StaticResource resuelve una clave para asignar el valor. DynamicResource mantiene la relación con esa clave y permite que el control reaccione si se sustituye su valor en el diccionario. La actividad 3 pide una nueva versión dinámica; no basta con cambiar una palabra y no probar ningún cambio.']),
      section('2. Definir y consumir las claves', ['Este fragmento usa el espaciado y fondo exigidos para matrícula en la relación 8. El ejemplo enseña la sintaxis del diccionario; para la relación 7 debes incluir también relleno, margen y tamaño de fuente, y los valores distintos por tipo de control.', 'Al cambiar Resources["Fondo"] por otro Color, un BackgroundColor con DynamicResource puede actualizarse. La clave debe ser exactamente la misma, incluidas mayúsculas, y el valor nuevo debe seguir siendo un Color.'], '<ContentView.Resources>\n    <x:Double x:Key="Espaciado">10</x:Double>\n    <Color x:Key="Fondo">Green</Color>\n</ContentView.Resources>\n\n<!-- Dentro del contenido de ese ContentView -->\n<VerticalStackLayout Spacing="{StaticResource Espaciado}"\n                     BackgroundColor="{DynamicResource Fondo}">\n    <Label Text="Matrícula del Vehículo" />\n</VerticalStackLayout>', 'xml', 'Fragmentos de recursos y consumo dentro de un ContentView'),
      section('3. Permitir configuración desde la aplicación', ['El PDF pide que las aplicaciones que integran los Views complejos puedan personalizar sus propiedades. Una propiedad pública puede servir para delegar un valor; una BindableProperty permite además asignación y enlace de datos propios de MAUI. La propiedad expuesta debe propagar su cambio a los elementos internos.', 'El ejemplo conecta la propiedad Fondo con la clave dinámica del fragmento anterior. El anfitrión asigna Fondo y el callback actualiza el recurso local. Si en cambio creases otra instancia del diccionario o escribieses una clave equivocada, los hijos seguirían mostrando el valor previo.'], 'public static readonly BindableProperty FondoProperty =\n    BindableProperty.Create(nameof(Fondo), typeof(Color), typeof(LoginView),\n        Colors.Green, propertyChanged: (obj, anterior, nuevo) =>\n        {\n            ((LoginView)obj).Resources["Fondo"] = (Color)nuevo;\n        });\n\npublic Color Fondo\n{\n    get => (Color)GetValue(FondoProperty);\n    set => SetValue(FondoProperty, value);\n}', 'csharp', 'Fragmento dentro de LoginView · junto con el recurso dinámico'),
      section('4. Verificación por mecanismo', ['Para recursos estáticos, comprueba que los valores iniciales se aplican y que cada clave tiene el tipo adecuado. Para dinámicos, cambia el valor de una clave del diccionario y observa que el control que la consume se actualiza.', 'Para la personalización, haz el cambio desde la aplicación de prueba, no solo editando el XAML interno de la biblioteca. La relación 8 vuelve a pedir cambiar espaciado, relleno y fondo desde la aplicación anfitriona: el dato debe recorrer la propiedad pública hasta el elemento visible.']),
      section('5. Estilos y recursos de aplicación en el módulo Learn', ['El módulo de recursos compartidos del listado también incluye estilos y recursos para toda la aplicación. Un Style agrupa Setter de propiedades para un TargetType. Con x:Key lo aplicas expresamente; un estilo sin clave puede aplicarse implícitamente al tipo correspondiente en su ámbito. Reunir varias propiedades en un estilo evita repetir sus asignaciones en cada control.', 'Los recursos de App.xaml están disponibles para la aplicación, mientras los de una página o ContentView pertenecen a un ámbito más cercano. Los proyectos recibidos contienen Resources/Styles/Colors.xaml y Styles.xaml para estudiar esta organización. Para la actividad 2 de la relación 7 sigue siendo obligatorio el diccionario a nivel de ContentView: conocer el ámbito global no cambia esa condición.'])
    ],
    pitfalls: ['Guardar todo en App.xaml cuando se pide ámbito ContentView.', 'Esperar actualización de un StaticResource al reemplazar la clave.', 'Publicar una propiedad que no actualiza ningún elemento interno.'],
    practice: { title: 'Relación 7 · actividades 2 y 3', prompt: 'Genera una versión de los Views con recursos estáticos en ContentView y una nueva versión con recursos dinámicos. Permite personalización desde la aplicación que los usa.', steps: ['Recursos para las cinco propiedades del PDF.', 'Claves diferenciadas por tipo de View.', 'Sustituye un recurso dinámico en ejecución y comprueba el cambio.', 'Modifica propiedades desde el anfitrión.'], solution: 'Los recursos locales reúnen valores con clave. StaticResource sirve para la asignación inicial; DynamicResource conserva la relación con la clave. Las propiedades públicas del View deben comunicar los cambios a su contenido. La demostración desde el anfitrión prueba que la biblioteca no tiene valores inaccesibles y fijos.' },
    checks: ['Tengo versión estática y dinámica.', 'Los recursos están en el ContentView.', 'El cambio desde el anfitrión llega a los hijos.'],
    quizzes: [quiz('Si se reemplaza una clave del diccionario en ejecución, ¿qué mecanismo conserva la relación para actualizar el valor?', ['DynamicResource', 'StaticResource', 'x:Name'], 0, 'DynamicResource mantiene la relación con la clave. StaticResource realiza la resolución inicial.')]
  },
  {
    id: 'matricula', unit: 'UD3-4', title: 'Relación 8 · ViewMatricula', tag: 'Relación 08 · A', minutes: 50,
    summary: 'Entrada 0000-BBB, validación al escribir y asignar, extensiones y mensajes de error.',
    sources: ['Relacion08_MAUI_2627'],
    goals: ['Respetar el formato literal y la exclusión de vocales.', 'Permitir lectura y actualización desde el anfitrión.'],
    sections: [
      section('1. Descomponer el contrato del control', ['La interfaz contiene una etiqueta “Matrícula del Vehículo”, entrada de datos y etiqueta informativa. El formato pedido es 0000-BBB: cuatro dígitos, un guion y tres letras que no sean vocales. El PDF no enumera otras exclusiones de matrículas reales; no añadas reglas administrativas que no aparecen en él.', 'El dato debe poder leerse y actualizarse desde el programa anfitrión, asegurando el formato. Eso significa que no basta con validar un evento del Entry: una asignación a la propiedad pública también tiene que pasar por la comprobación. Un valor rechazado no debería sustituir al último valor válido.']),
      section('2. Una regla compartida para las dos vías de entrada', ['El fragmento expresa el patrón en mayúsculas del enunciado, limitado al alfabeto A–Z. El documento no detalla normalización automática ni letras fuera de ese alfabeto; el ejemplo no convierte minúsculas ni elimina guiones. Si necesitas resolver esas ambigüedades, el criterio debe venir del profesor.', 'Coloca esta comprobación en un método compartido. Tanto el evento que procesa texto como el setter de la propiedad pública deben utilizarlo. La comprobación debe cubrir el valor completo; aceptar una coincidencia en medio de una cadena más larga sería incorrecto.'], 'using System.Text.RegularExpressions;\n\nstatic bool MatriculaValida(string? valor) =>\n    valor is not null && Regex.IsMatch(valor,\n        @"\A[0-9]{4}-[B-DF-HJ-NP-TV-Z]{3}\z");', 'csharp', 'Fragmento didáctico · formato literal 0000-BBB'),
      section('3. Retroalimentación y aspecto requeridos', ['Sin error, la etiqueta informativa permanece con fondo transparente. Cuando hay error, muestra información y el fondo pasa a amarillo. Al corregir el dato hay que borrar el mensaje anterior y recuperar el fondo transparente: cambiar solo el texto deja un estado visual incoherente.', 'Todos los espacios de separación y rellenos se establecen mediante extensión con 10 unidades. Los StackLayout tienen fondo verde, también mediante extensión. Recuerda la diferencia de tipos: Spacing es numérico, Padding es Thickness y BackgroundColor es Color. La aplicación de prueba debe poder cambiar espaciado, relleno y fondo y ver el resultado.']),
      section('4. Publicar el dato y no solo el Entry', ['Expón una propiedad de lectura y escritura para la matrícula. En el setter valida antes de almacenar y reflejar el texto en la entrada. Si usas BindableProperty, la validación debe cubrir también SetValue y debes conectar sus cambios al contenido del control.', 'No hace falta imitar trámites de matriculación ni conectar una base de datos. La actividad trata de construir una biblioteca de Views y probar su integración. El PDF utiliza nombres BRelacion07 y PruebasR07 aunque el archivo se titule relación 8; conserva esa discrepancia visible al seguir los nombres de entrega.'])
    ],
    pitfalls: ['Validar solo lo escrito con el teclado.', 'Permitir vocales o una cadena más larga que contiene una matrícula.', 'Mantener la etiqueta amarilla después de corregir el error.', 'Añadir restricciones de matrículas reales que no pide el PDF.'],
    practice: { title: 'Relación 8 · ejercicio 1', prompt: 'Construye ViewMatricula con la disposición del PDF, lectura y escritura de matrícula desde la aplicación y las extensiones y estados de error indicados.', steps: ['Verifica 0000-BBB y rechaza vocales o formato incorrecto.', 'Prueba asignación válida e inválida desde el anfitrión.', 'Comprueba 10 unidades, StackLayout verde y etiqueta de error amarilla/transparente.'], solution: 'Una validación completa controla cuatro dígitos, guion y tres letras sin vocales. El mismo contrato debe cumplirse cuando se escribe y cuando se asigna desde la aplicación. Se rechaza el valor inválido antes de actualizar el estado. Los cambios de formato y los errores se reflejan en la etiqueta informativa, sin bloquear la reutilización del control.' },
    checks: ['Formato completo 0000-BBB sin vocales.', 'La propiedad permite leer y actualizar con validación.', 'Extensiones de 10 unidades y fondo verde.', 'Error amarillo y estado correcto transparente.'],
    quizzes: [quiz('¿Qué ocurre con la etiqueta informativa cuando desaparece el error?', ['Recupera fondo transparente', 'Permanece amarilla', 'El PDF exige eliminar el control'], 0, 'El documento indica fondo transparente sin error y amarillo cuando muestra un error.')]
  },
  {
    id: 'edad', unit: 'UD3-4', title: 'Relación 8 · ViewMayorEdad', tag: 'Relación 08 · B', minutes: 55,
    summary: 'DatePicker, cálculo de años cumplidos y un límite configurable estrictamente superior a 12.',
    sources: ['Relacion08_MAUI_2627'],
    goals: ['Calcular edad sin equivocarse antes del cumpleaños.', 'Rechazar futuro y validar el límite configurable.'],
    sections: [
      section('1. Qué contiene y qué expone el View', ['El título es “Fecha Nacimiento”. Se elige fecha mediante DatePicker; una etiqueta muestra edad y otra informa de errores. Debe permitirse obtener la fecha de nacimiento y la edad. Si no alcanza la mayoría configurada, el mensaje es “No eres mayor de edad”. Si la fecha es futura, se informa de ese error.', 'La mayoría de edad por defecto es 18 y la configuración siempre debe ser superior a 12. No es “12 o más”: 12 no es válido y 13 sí supera el mínimo de configuración. Cambiar el límite desde el anfitrión debe recalcular el estado de la fecha ya seleccionada.']),
      section('2. Años cumplidos, no diferencia de años', ['Restar los años da una primera aproximación. Si el cumpleaños de este año aún no ha llegado, se resta uno. Compara fechas sin horas para que la hora del día no haga fallar un cumpleaños.', 'El fragmento recibe hoy como parámetro para poder comprobar fronteras de forma controlada. DateTime.Today sirve como valor al usarlo en el control. El PDF no detalla qué convención aplicar a nacidos un 29 de febrero en años no bisiestos; AddYears sigue la convención de .NET. Esta decisión se indica para no presentarla como una regla expresa del profesor.'], 'static int CalcularEdad(DateTime nacimiento, DateTime hoy)\n{\n    nacimiento = nacimiento.Date;\n    hoy = hoy.Date;\n    if (nacimiento > hoy)\n        throw new ArgumentException("La fecha no puede ser futura.");\n\n    int edad = hoy.Year - nacimiento.Year;\n    if (nacimiento.AddYears(edad) > hoy) edad--;\n    return edad;\n}', 'csharp', 'Fragmento didáctico de años cumplidos'),
      section('3. Orden de las comprobaciones', ['Primero detecta si la fecha está en el futuro. Si no, calcula la edad y compárala con el límite configurado. Una fecha futura no debería acabar mostrando únicamente “No eres mayor de edad”, porque el PDF pide informar de esa circunstancia específica.', 'Al modificar fecha o límite, actualiza edad, texto informativo y fondo. Sin error, el fondo de la etiqueta informativa es transparente; con error, amarillo. La lógica no debe depender de que el usuario haya tocado antes el DatePicker: el control necesita un estado inicial coherente.']),
      section('4. Aspecto e integración final', ['Separación y relleno: extensiones de 10 unidades. Fondo de StackLayout: azul mediante extensión. La parte final pide integrar ambos Views en la aplicación de prueba, añadir un botón para mostrar los datos y modificar espaciado, relleno y fondo para comprobar que los cambios se ven.', 'Si el anfitrión asigna un límite no válido, rechaza el cambio antes de sustituir el valor anterior. La regla pertenece al control, no solo al formulario que lo configura. Para estudiar, prueba fecha de hoy, fecha futura, cumpleaños de hoy y víspera de cumpleaños. Son comprobaciones derivadas de los límites del documento, no nuevos ejercicios.'])
    ],
    pitfalls: ['Calcular edad solo con hoy.Year - nacimiento.Year.', 'Aceptar límite 12 por usar >= en vez de >.', 'No recalcular cuando cambia el límite.', 'Ocultar el error de futuro bajo un mensaje de minoría de edad.'],
    practice: { title: 'Relación 8 · ejercicio 2 e integración', prompt: 'Construye ViewMayorEdad con DatePicker, edad y mensaje. Integra los dos Views de la relación en la biblioteca y aplicación indicadas en el PDF y prueba cambios de apariencia desde el anfitrión.', steps: ['Fecha y edad accesibles; futuro con error específico.', 'Umbral por defecto 18 y configuración siempre >12.', 'Años cumplidos y actualización al cambiar fecha o límite.', 'Extensiones 10, fondo azul y etiqueta amarilla/transparente.'], solution: 'El cálculo ajusta la diferencia de años si falta el cumpleaños. La comparación de mayoría usa el límite configurable ya validado. Los dos errores son distintos: fecha futura y edad inferior al límite. La aplicación de prueba verifica tanto los datos expuestos como que los cambios públicos de aspecto llegan al interior de los Views.' },
    checks: ['Expongo nacimiento y edad.', 'Futuro y minoría tienen retroalimentación.', 'El límite inicia en 18 y rechaza valores <=12.', 'Recalculo fecha y límite; aspecto según PDF.'],
    quizzes: [quiz('¿Qué valor del límite configurable incumple la condición del PDF?', ['12', '13', '18'], 0, 'El valor siempre debe ser superior a 12. El valor por defecto es 18, pero puede configurarse otro que cumpla esa condición.')]
  }
];

