lessons.push({
  id: 'extensiones-login', unit: 'UD3-4', title: 'Relación 7 · espaciado de la contraseña', tag: 'Relación 07 · C', minutes: 45,
  summary: 'Cuatro formas de resolver el espaciado de EntryContrasenia: extensión propia, x:Static, StaticResource y DynamicResource, comparadas entre V0 y V1.',
  sources: ['Relacion07_MAUI_2627', 'R07E01R05_V0_JesusCG', 'R07E01R05_V1_JesusCG'],
  goals: ['Distinguir cuatro mecanismos que producen el mismo valor de Spacing.', 'Reconocer qué se resuelve en V1 y qué queda pendiente, sin completarlo por conjetura.'],
  sections: [
    section('1. De V0 a V1: solo cambia el espaciado de la contraseña', ['V0 contiene la base de la relación 5: EntryNombreUsuarioV1 a V5 y EntryContraseniaV1 a V5, sin personalizar. V1 añade Spacing únicamente en EntryContrasenia, en sus variantes V2 a V5. EntryNombreUsuario no cambia entre V0 y V1.', 'El ejercicio 1 de la relación 7 pide personalizar espaciado, relleno, margen, color de fondo y tamaño de fuente. V1 solo resuelve el espaciado. Relleno, margen, color de fondo y tamaño de fuente no están resueltos en V1 y esta lección no los resuelve ni propone una solución para ellos: es una limitación del material, no una decisión tuya pendiente de comprobar.']),
    section('2. V2: una extensión de marcado propia', ['EspaciadoExtension implementa IMarkupExtension. Su método ProvideValue consulta DeviceInfo.Platform: en WinUI devuelve la constante de Windows y en Android la de Android. En cualquier otra plataforma queda el valor 0. El XAML la usa con Spacing="{codigo:Espaciado}".', 'La extensión devuelve un double, que es el tipo de Spacing. El valor se decide en código C#; el XAML solo la invoca.'], 'public class EspaciadoExtension : IMarkupExtension\n{\n    public object ProvideValue(IServiceProvider serviceProvider)\n    {\n        string plataforma = DeviceInfo.Platform.ToString();\n        double espaciado = 0;\n        switch (plataforma)\n        {\n            case "WinUI":\n                espaciado = EntryContraseniaV2.EspaciadoWindows;\n                break;\n            case "Android":\n                espaciado = EntryContraseniaV2.EspaciadoAndroid;\n                break;\n        }\n        return espaciado;\n    }\n}', 'csharp', 'EntryContraseniaV2.xaml.cs · EspaciadoExtension'),
    section('3. V3: OnPlatform con x:Static', ['V3 elimina la clase de extensión. Spacing se declara como elemento de propiedad con un OnPlatform de tipo double, y cada On toma una constante pública del control mediante x:Static. La decisión de plataforma pasa de C# a XAML.'], '<StackLayout.Spacing>\n    <OnPlatform x:TypeArguments="x:Double">\n        <On Platform="Android" Value="{x:Static Member=codigo:EntryContraseniaV3.EspaciadoAndroid}" />\n        <On Platform="WinUI" Value="{x:Static Member=codigo:EntryContraseniaV3.EspaciadoWindows}" />\n    </OnPlatform>\n</StackLayout.Spacing>', 'xml', 'EntryContraseniaV3.xaml · OnPlatform y x:Static'),
    section('4. V4: StaticResource en ContentView.Resources', ['V4 mueve los valores a ContentView.Resources, con una clave x:Double para cada plataforma. StaticResource busca la clave una vez, al cargar el XAML. El code-behind coincide con el de V1, salvo el nombre de la clase.'], '<ContentView.Resources>\n    <x:Double x:Key="EspaciadoAndroid">10</x:Double>\n    <x:Double x:Key="EspaciadoWindows">20</x:Double>\n</ContentView.Resources>\n\n<On Platform="Android" Value="{StaticResource EspaciadoAndroid}" />\n<On Platform="WinUI" Value="{StaticResource EspaciadoWindows}" />', 'xml', 'EntryContraseniaV4.xaml · recursos estáticos'),
    section('5. V5: DynamicResource y propiedades de configuración', ['V5 usa las mismas claves con DynamicResource, que conserva la relación con la clave. Además añade al code-behind dos propiedades públicas, EspaciadoAndroid y EspaciadoWindows, que leen y escriben this.Resources. En el RAR, V5 escribe DynamicResource dentro de OnPlatform, pero On.Value no es una propiedad enlazable y no se ha ejecutado ese original. El paquete de estudio conserva las claves y enlaza Spacing en el constructor con SetDynamicResource.', 'Así la aplicación anfitriona puede cambiar el espaciado: asigna la propiedad, se reemplaza el valor del diccionario y el StackLayout se actualiza. La clave debe escribirse exactamente igual en C# y en XAML.'], 'public double EspaciadoAndroid\n{\n    get { return (double)this.Resources["EspaciadoAndroid"]; }\n    set { this.Resources["EspaciadoAndroid"] = value; }\n}\n\npublic double EspaciadoWindows\n{\n    get { return (double)this.Resources["EspaciadoWindows"]; }\n    set { this.Resources["EspaciadoWindows"] = value; }\n}', 'csharp', 'EntryContraseniaV5.xaml.cs · propiedades de configuración'),
    section('6. Una aplicación anfitriona para comprobarlo', ['El MainPage del RAR es la plantilla sin usar: no contiene ninguno de los controles. El paquete de esta lección añade una aplicación anfitriona mínima con una instancia de cada variante y un botón que cambia el espaciado de V5. Es una elaboración didáctica añadida, no parte del RAR.'])
  ],
  pitfalls: ['Copiar DynamicResource dentro de OnPlatform como en el RAR: On.Value no es una propiedad enlazable, así que este paquete usa SetDynamicResource sobre Spacing.', 'Dar por resueltos relleno, margen, color de fondo y tamaño de fuente: V1 no los resuelve.', 'Esperar que StaticResource actualice el espaciado al cambiar el diccionario.', 'Escribir en Resources una clave distinta de la declarada en el XAML.', 'Suponer que EntryNombreUsuario cambia en V1.'],
  practice: { title: 'Relación 7 · ejercicio 1 · espaciado de V1', prompt: 'Compara las cuatro variantes del espaciado de la contraseña y comprueba el efecto de DynamicResource desde una aplicación anfitriona.', steps: ['Parte de EntryContraseniaV1, sin Spacing.', 'Resuelve el espaciado con una extensión propia (V2).', 'Hazlo con OnPlatform y x:Static (V3), y con recursos estáticos (V4).', 'Usa recursos dinámicos y cambia el valor desde el anfitrión (V5).'], solution: 'V2 decide el valor en C# con IMarkupExtension. V3 lo decide en XAML con OnPlatform y constantes. V4 lo resuelve una vez con StaticResource. V5 mantiene la referencia con DynamicResource y expone propiedades que escriben el diccionario. Relleno, margen, color de fondo y tamaño de fuente no están resueltos en V1.' },
  checks: ['Distingo las cuatro variantes del espaciado.', 'Sé que V1 solo resuelve el espaciado de la contraseña.', 'Sé que EntryNombreUsuario no cambia en V1.', 'Probé V5 desde la aplicación anfitriona.'],
  quizzes: [
    quiz('¿Qué decide el espaciado según la plataforma en V2?', ['EspaciadoExtension.ProvideValue', 'Un diccionario de Application', 'Un evento Unfocused'], 0, 'La extensión consulta DeviceInfo.Platform y devuelve el double correspondiente.'),
    quiz('¿Qué resuelve x:Static en V3?', ['Una constante pública del control', 'Una clave de ContentView.Resources', 'El valor de Platform'], 0, 'x:Static obtiene un miembro estático; las claves de recursos pertenecen a V4 y V5.'),
    quiz('¿Cuándo resuelve StaticResource su clave?', ['Una vez, al cargar el XAML', 'Cada vez que cambia el diccionario', 'Al perder el foco'], 0, 'StaticResource no mantiene la relación con la clave; DynamicResource sí.'),
    quiz('¿Qué hace posible que V5 cambie el espaciado desde el anfitrión?', ['Propiedades que escriben this.Resources con DynamicResource vinculado', 'Una nueva extensión de marcado', 'Cambiar el código de EntryNombreUsuario'], 0, 'La propiedad reemplaza el valor de la clave y DynamicResource actualiza el StackLayout.'),
    quiz('¿Qué personalizaciones de la relación 7 resuelve V1?', ['Solo el espaciado de la contraseña', 'Espaciado y relleno', 'Las cinco propiedades'], 0, 'Relleno, margen, color de fondo y tamaño de fuente no están resueltos en V1.')
  ]
});

